$insert = $pdo->prepare('INSERT INTO categories (name, parent_id, icon, is_custom, created_by, sort_order) VALUES (?, ?, ?, 0, NULL, 50)');
$idFor = function (string $name, ?int $parentId) use ($pdo, $insert): int {
    $stmt = $pdo->prepare('SELECT id FROM categories WHERE name = ? AND ' . ($parentId === null ? 'parent_id IS NULL' : 'parent_id = ?') . ' LIMIT 1');
    $args = $parentId === null ? [$name] : [$name, $parentId];
    $stmt->execute($args);
    $id = $stmt->fetchColumn();
    if ($id !== false) return (int) $id;
    $insert->execute([$name, $parentId, '']);
    return (int) $pdo->lastInsertId();
};

$pdo->beginTransaction();
try {
    foreach ($tree as $rootName => $subcategories) {
        $rootId = $idFor($rootName, null);
        foreach ($subcategories as $subName => $leaves) {
            $subId = $idFor($subName, $rootId);
            foreach ($leaves as $leafName) $idFor($leafName, $subId);
        }
    }
    if (getenv('ICOOK_CATEGORY_SEED_DRY_RUN') === '1') {
        $pdo->rollBack();
        echo "Dry run successful; transaction rolled back.\n";
    } else {
        $pdo->commit();
        echo "Category tree seeded successfully.\n";
    }
} catch (Throwable $error) {
    $pdo->rollBack();
    fwrite(STDERR, $error->getMessage() . "\n");
    exit(1);
}
